package com.smartseating.ui;

import com.smartseating.dao.*;
import com.smartseating.model.*;
import com.smartseating.service.*;
import com.smartseating.util.*;
import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;

public class GenerateSeatingFrame extends AppFrame {
    private final ExamDAO examDAO=new ExamDAO();private final RoomDAO roomDAO=new RoomDAO();private final SeatingDAO seatingDAO=new SeatingDAO();private final ExamService service=new ExamService();private final JComboBox<Exam> exams=new JComboBox<>();private final JComboBox<String> shuffle=new JComboBox<>(ShuffleService.OPTIONS);private final JRadioButton automatic=new JRadioButton("AUTOMATIC",true),manual=new JRadioButton("MANUAL");private final JList<Room> roomList=new JList<>();private final JLabel students=new JLabel("—"),capacity=new JLabel("—"),required=new JLabel("—"),empty=new JLabel("—"),status=new JLabel("Select an exam to begin");
    public GenerateSeatingFrame(User user){super("Generate Seating Arrangement",user);UI.frame(this,1080,700);build();loadExams();}
    private void build(){content.add(title("Generate Seating Arrangement"),BorderLayout.NORTH);JPanel left=UI.formPanel();UI.addField(left,0,"Examination",exams);UI.addField(left,1,"Shuffle Order",shuffle);JPanel mode=new JPanel(new FlowLayout(FlowLayout.LEFT,4,0));mode.setOpaque(false);ButtonGroup group=new ButtonGroup();group.add(automatic);group.add(manual);mode.add(automatic);mode.add(manual);UI.addField(left,2,"Room Selection Mode",mode);UI.addField(left,3,"Available / Select Rooms",UI.scroll(roomList));roomList.setVisibleRowCount(11);roomList.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);JPanel stats=UI.formPanel();UI.addField(stats,0,"Students Selected",students);UI.addField(stats,1,"Selected Capacity",capacity);UI.addField(stats,2,"Required Rooms",required);UI.addField(stats,3,"Empty Seats",empty);GridBagConstraints sg=new GridBagConstraints();sg.gridx=0;sg.gridy=4;sg.gridwidth=2;sg.fill=GridBagConstraints.HORIZONTAL;sg.insets=new Insets(12,6,6,6);stats.add(status,sg);JPanel controls=new JPanel(new FlowLayout(FlowLayout.LEFT,7,0));controls.setOpaque(false);JButton generate=button("GENERATE SEATING",UI.TEAL),clear=button("CLEAR",UI.MUTED),print=button("PRINT CAPACITY",UI.ORANGE),clearExisting=button("CLEAR EXISTING SEATING",new Color(190,66,66));controls.add(generate);controls.add(clear);controls.add(print);if("ADMIN".equals(currentUser.getRole()))controls.add(clearExisting);sg.gridy=5;stats.add(controls,sg);JPanel top=new JPanel(new BorderLayout(10,0));top.setOpaque(false);top.add(white(left),BorderLayout.WEST);top.add(white(stats),BorderLayout.CENTER);content.add(top,BorderLayout.CENTER);JLabel hint=new JLabel("Automatic allocation uses the fewest available rooms. Manual mode requires enough selected capacity.");hint.setForeground(UI.MUTED);content.add(hint,BorderLayout.SOUTH);exams.addActionListener(e->examChanged());automatic.addActionListener(e->roomMode());manual.addActionListener(e->roomMode());roomList.addListSelectionListener(e->metrics());generate.addActionListener(e->generate());clear.addActionListener(e->reset());print.addActionListener(e->PrintService.print("Capacity Before Generation",capacityReport()));clearExisting.addActionListener(e->clearExisting());}
    private void loadExams(){try{for(Exam e:examDAO.findAll())exams.addItem(e);}catch(Exception ex){error(ex);}}
    private void examChanged(){try{Exam e=(Exam)exams.getSelectedItem();if(e==null)return;int count=service.studentsFor(e).size();students.setText(String.valueOf(count));roomList.setModel(new DefaultListModel<>());DefaultListModel<Room> model=new DefaultListModel<>();for(Room r:roomDAO.findAvailable())model.addElement(r);roomList.setModel(model);metrics();}catch(Exception ex){error(ex);}}
    private void roomMode(){roomList.setEnabled(manual.isSelected());metrics();}
    private void metrics(){try{int n=parse(students.getText()),cap=0,rooms=0;if(manual.isSelected()){for(Room r:roomList.getSelectedValuesList()){cap+=r.getCapacity();rooms++;}}else{List<Room> all=new ArrayList<>();for(int i=0;i<roomList.getModel().getSize();i++)all.add(roomList.getModel().getElementAt(i));List<Room> chosen=new RoomAllocationService().automatic(all,n);cap=chosen.stream().mapToInt(Room::getCapacity).sum();rooms=chosen.size();}capacity.setText(String.valueOf(cap));required.setText(String.valueOf(new RoomAllocationService().requiredRooms(n,rooms==0?0:cap/rooms)));empty.setText(String.valueOf(Math.max(0,cap-n)));status.setText(cap>=n&&n>0?"CAPACITY OK • "+rooms+" room(s) will be used":"CAPACITY LOW • Select more rooms or another exam");status.setForeground(cap>=n&&n>0?UI.TEAL:new Color(190,66,66));}catch(Exception ex){capacity.setText("—");required.setText("—");empty.setText("—");}}
    private int parse(String value){try{return Integer.parseInt(value);}catch(Exception e){return 0;}}
    private void generate(){try{Exam e=(Exam)exams.getSelectedItem();if(e==null)throw new IllegalArgumentException("No examination is selected.");if(seatingDAO.countForExam(e.getId())>0&&!confirm("A seating arrangement already exists. Regenerate it with the selected shuffle and rooms?"))return;List<Room> chosen=manual.isSelected()?roomList.getSelectedValuesList():List.of();ExamService.GenerationSummary result=service.generate(e,(String)shuffle.getSelectedItem(),automatic.isSelected(),chosen);new SeatingResultFrame(currentUser,result).setVisible(true);}catch(Exception ex){error(ex);}}
    private void clearExisting(){try{Exam e=(Exam)exams.getSelectedItem();if(e==null)throw new IllegalArgumentException("Select an exam first.");if(confirm("Are you sure you want to delete the existing seating arrangement? This does not delete students or exams.")){service.clear(e.getId());JOptionPane.showMessageDialog(this,"Seating cleared for "+e.getName(),"Cleared",JOptionPane.INFORMATION_MESSAGE);}}catch(Exception ex){error(ex);}}
    private void reset(){exams.setSelectedItem(null);students.setText("—");capacity.setText("—");required.setText("—");empty.setText("—");roomList.setModel(new DefaultListModel<>());status.setText("Select an exam to begin");}
    private String capacityReport(){return "CAPACITY BEFORE GENERATION\n\nExam: "+(exams.getSelectedItem()==null?"":exams.getSelectedItem())+"\nStudents: "+students.getText()+"\nCapacity: "+capacity.getText()+"\nRequired rooms: "+required.getText()+"\nEmpty seats: "+empty.getText()+"\nStatus: "+status.getText();}
}
